changeSet.sql:

CREATE OR REPLACE FUNCTION public.fn_set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_channel_updated_at
    BEFORE UPDATE ON public.channel
    FOR EACH ROW
    EXECUTE FUNCTION public.fn_set_updated_at();

CREATE TRIGGER trg_campaign_updated_at
    BEFORE UPDATE ON public.campaign
    FOR EACH ROW
    EXECUTE FUNCTION public.fn_set_updated_at();

CREATE TRIGGER trg_campaign_metric_updated_at
    BEFORE UPDATE ON public.campaign_metric
    FOR EACH ROW
    EXECUTE FUNCTION public.fn_set_updated_at();

rollback.sql:

DROP TRIGGER IF EXISTS trg_channel_updated_at ON public.channel;
DROP TRIGGER IF EXISTS trg_campaign_updated_at ON public.campaign;
DROP TRIGGER IF EXISTS trg_campaign_metric_updated_at ON public.campaign_metric;
DROP FUNCTION IF EXISTS public.fn_set_updated_at();
